from app.models import Base
from sqlalchemy import Table,Column,String,Integer,Boolean,DateTime,Date,Numeric,CHAR,ForeignKey,text
from sqlalchemy.dialects.postgresql import UUID

def common():return [Column('id',UUID(as_uuid=True),primary_key=True,server_default=text('gen_random_uuid()')),Column('created_at',DateTime(timezone=True),server_default=text('now()')),Column('updated_at',DateTime(timezone=True),server_default=text('now()')),Column('created_by',UUID(as_uuid=True),ForeignKey('users.id')),Column('updated_by',UUID(as_uuid=True),ForeignKey('users.id')),Column('version',Integer,server_default='1')]
def table(name,*columns):return Table(name,Base.metadata,*common(),*columns)
platform_fee_policies_table=table('platform_fee_policies',Column('effective_from',DateTime(timezone=True)),Column('fee_rate',Numeric(7,6)),Column('status',String(12)),Column('approved_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('approved_at',DateTime(timezone=True)))
trip_payments_table=table('trip_payments',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('booking_id',UUID(as_uuid=True),ForeignKey('bookings.id')),Column('payer_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('payment_method',String(12)),Column('provider_code',String(32)),Column('provider_reference',String(120)),Column('provider_callback_hash',CHAR(64)),Column('amount',Numeric(12,2)),Column('currency',CHAR(3)),Column('status',String(32)),Column('initiated_at',DateTime(timezone=True)),Column('provider_confirmed_at',DateTime(timezone=True)),Column('passenger_cash_confirmed_at',DateTime(timezone=True)),Column('driver_cash_received_at',DateTime(timezone=True)),Column('driver_cash_handover_at',DateTime(timezone=True)),Column('confirmed_at',DateTime(timezone=True)),Column('held_by_driver_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('provider_fee_amount',Numeric(12,2)),Column('fee_policy_id',UUID(as_uuid=True),ForeignKey('platform_fee_policies.id')),Column('platform_fee_rate',Numeric(7,6)),Column('platform_fee_amount',Numeric(12,2)),Column('owner_payable_amount',Numeric(12,2)))
owner_settlements_table=table('owner_settlements',Column('trip_id',UUID(as_uuid=True),ForeignKey('trips.id')),Column('payment_id',UUID(as_uuid=True),ForeignKey('trip_payments.id')),Column('owner_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('gross_fare_amount',Numeric(12,2)),Column('platform_fee_rate',Numeric(7,6)),Column('platform_fee_amount',Numeric(12,2)),Column('provider_fee_amount',Numeric(12,2)),Column('reimbursement_amount',Numeric(12,2)),Column('owner_payable_amount',Numeric(12,2)),Column('status',String(24)),Column('driver_handover_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')),Column('driver_handover_at',DateTime(timezone=True)),Column('owner_received_at',DateTime(timezone=True)),Column('owner_received_by_user_id',UUID(as_uuid=True),ForeignKey('users.id')))
vehicle_maintenance_schedules_table=table('vehicle_maintenance_schedules',Column('vehicle_id',UUID(as_uuid=True),ForeignKey('vehicles.id')),Column('maintenance_type',String(32)),Column('custom_label',String(120)),Column('interval_km',Numeric(12,1)),Column('interval_days',Integer),Column('next_due_odometer_km',Numeric(12,1)),Column('next_due_date',Date),Column('active',Boolean))
class PlatformFeePolicy(Base):__table__=platform_fee_policies_table
class TripPayment(Base):__table__=trip_payments_table
class OwnerSettlement(Base):__table__=owner_settlements_table
class VehicleMaintenanceSchedule(Base):__table__=vehicle_maintenance_schedules_table
